(function(){
  'use strict';
  const K=window.KingshotTiming,I=window.KingshotI18n,t=(k,p)=>I.t(k,p);
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function countdown(seconds){const ticks=Math.ceil(Math.max(0,seconds)*10),whole=Math.floor(ticks/10);return (whole>=3600?Math.floor(whole/3600)+':':'')+String(Math.floor(whole/60)%60).padStart(2,'0')+':'+String(whole%60).padStart(2,'0')+'.'+ticks%10;}
  const localTime=at=>new Date(at-new Date(at).getTimezoneOffset()*60000).toISOString().slice(0,23);
  function orders(rows,editable=false){
    return rows.map(r=>`<article class="rally-order" data-order-id="${esc(r.id)}"><header><b>${esc(r.name)}</b><span class="pill neutral">${t(r.confirmed?'calibrated':'estimatedLaunch')}</span></header><div class="order-times"><div><small>${t('rallyLaunchTime')}</small><strong>${esc(K.formatUtc(r.launchAt))}</strong></div><div><small>${t('attackArrival')}</small><strong>${esc(K.formatUtc(r.arrivalAt))}</strong></div></div><div class="order-countdown"><span data-order-stage></span><strong data-order-countdown></strong></div><small>${esc(t('orderDurations',{prepare:r.prepareSeconds,march:r.marchSeconds}))}</small>${editable?`<details class="launch-calibration"><summary>${t('calibrateLaunch')}</summary><p>${t('calibrateHint')}</p><div class="time-nudges">${[-1,-0.1,0.1,1].map(d=>`<button type="button" data-rally-delta="${d}">${d>0?'+':'−'}${Math.abs(d)}s</button>`).join('')}</div><button type="button" class="button secondary" data-rally-now>${t('launchObservedNow')}</button><label>${t('actualLaunchLocal')}<input type="datetime-local" step="0.001" data-rally-at value="${localTime(r.launchAt)}"></label><button type="button" class="text-button" data-rally-set>${t('applyLaunchTime')}</button></details>`:''}</article>`).join('');
  }
  function tick(container,rows,time){for(const r of rows){const card=container.querySelector(`[data-order-id="${CSS.escape(r.id)}"]`);if(!card)continue;const timing=K.rallyTiming(r,time),stage=timing.stage==='waiting'?'launchCountdown':timing.stage==='launch'?'launchNow':timing.stage==='gathering'?'prepareRemaining':timing.stage==='marching'?'marchRemaining':'arrived';card.querySelector('[data-order-stage]').textContent=t(stage);card.querySelector('[data-order-countdown]').textContent=timing.stage==='launch'?t('launch'):timing.stage==='arrived'?'—':countdown(timing.remaining);card.classList.toggle('go',timing.stage==='launch');}}
  function gaps(rows){
    if(rows.length<2)return `<p class="result-placeholder">${t('gapNeedTwo')}</p>`;
    return K.rallyGaps(rows,0).map(g=>`<div class="rally-gap ${g.usable?'has-gap':''}"><div><b>${esc(g.before.name)} → ${esc(g.after.name)}</b><small>${esc(t('landingGap',{seconds:I.number(g.width)}))}</small></div><div><strong>${g.usable?esc(t('insertionWidth',{seconds:I.number(g.safeWidth)})):t('noInsertionWindow')}</strong>${g.usable?`<small>${esc(K.formatUtc(g.start))} – ${esc(K.formatUtc(g.end).slice(11))}</small>`:''}</div></div>`).join('');
  }
  const advisors=new WeakMap();
  function boostItems(plan){return [plan.n50?t('boostCount',{percent:50,n:plan.n50}):'',plan.n25?t('boostCount',{percent:25,n:plan.n25}):''].filter(Boolean).join(' + ')||t('boostNoItems');}
  function boostAdvisor(container,windows,march,time,{key='local',enabled=true}={}){
    const storageKey='kingshot:'+new URL('.',location.href).pathname+':boost:'+key;
    let view=advisors.get(container);
    if(!view||view.key!==storageKey){
      let options={delay:'1',stock25:'',stock50:''};
      try{const saved=JSON.parse(localStorage.getItem(storageKey));if(saved)for(const k of Object.keys(options))if(typeof saved[k]==='string')options[k]=saved[k];}catch{}
      view={key:storageKey,options,language:null,signature:null};advisors.set(container,view);
      if(!container.dataset.boostBound){container.dataset.boostBound='true';container.addEventListener('input',e=>{
        if(!e.target.matches('[data-boost-setting]'))return;
        const current=advisors.get(container);current.options[e.target.dataset.boostSetting]=e.target.value;
        try{localStorage.setItem(current.key,JSON.stringify(current.options));}catch{}
        window.dispatchEvent(new Event('kingshot:boost-settings'));
      });}
    }
    if(view.language!==I.language){
      const open=container.querySelector('details')?.open;
      container.innerHTML=`<p class="field-note">${t('boostHint')}</p><p class="field-note" data-boost-assumption></p><details class="boost-settings" ${open?'open':''}><summary>${t('boostSettings')}</summary><div class="field-grid"><label>${t('boostStock',{percent:25})}<input type="number" min="0" max="9999" step="1" data-boost-setting="stock25" placeholder="${t('boostUnlimited')}" value="${esc(view.options.stock25)}"></label><label>${t('boostStock',{percent:50})}<input type="number" min="0" max="9999" step="1" data-boost-setting="stock50" placeholder="${t('boostUnlimited')}" value="${esc(view.options.stock50)}"></label><label>${t('boostDelay')}<input type="number" min="0.1" max="30" step="0.1" data-boost-setting="delay" value="${esc(view.options.delay)}"></label></div><p class="field-note">${t('boostSettingsHint')}</p></details><p class="form-error" data-boost-error role="alert" hidden></p><div data-boost-results></div>`;
      view.language=I.language;view.signature=null;
    }
    const assumption=container.querySelector('[data-boost-assumption]'),assumptionText=t('boostAssumption',{delay:view.options.delay});
    if(assumption.textContent!==assumptionText)assumption.textContent=assumptionText;
    let analyses=[],invalid=false;
    if(enabled&&march)try{analyses=K.reinforcementBoosts(windows,march,time,view.options);}catch{invalid=true;}
    const error=container.querySelector('[data-boost-error]');error.hidden=!invalid;error.textContent=invalid?t('boostInvalid'):'';
    const result=container.querySelector('[data-boost-results]');
    const planKey=p=>p&&[p.n25,p.n50,p.seconds,p.start,p.end,p.start<=time+Number(view.options.delay)*1000];
    const signature=JSON.stringify([enabled,!!march,invalid,analyses.map(a=>[a.window.id,a.window.before.name,a.window.after.name,planKey(a.normal),planKey(a.recommended),planKey(a.only25),planKey(a.only50)])]);
    if(view.signature!==signature){
      result.innerHTML=analyses.length?analyses.map((a,i)=>{
        const w=a.window,p=a.recommended,normal=!!a.normal;
        const range=plan=>`${plan.start<=time+Number(view.options.delay)*1000?t('boostReady'):esc(K.formatUtc(plan.start))} → ${esc(K.formatUtc(plan.end))}`;
        const alternatives=[a.only25,a.only50].filter((p,i,all)=>p&&p.count>0&&(p.n25!==a.recommended?.n25||p.n50!==a.recommended?.n50)&&all.indexOf(p)===i);
        return `<article class="boost-window ${p&&!normal?'needs-boost':''}" data-boost-window="${i}"><header><b>${esc(w.before.name||t('enemyName',{n:i+1}))} → ${esc(w.after.name||t('enemyName',{n:i+2}))}</b><span class="pill neutral">${t(normal?'boostNormal':p?'boostReachable':'boostCannotReach')}</span></header><p class="boost-landing"><span>${t('battleArrival')} · ${esc(I.number(w.width))} ${t('seconds')}</span><strong>${esc(K.formatUtc(w.arrivalStart))} → ${esc(K.formatUtc(w.arrivalEnd))}</strong></p>${p?`<div class="boost-recommendation"><b>${normal?t('boostNoItems'):esc(t('boostRecommend',{items:boostItems(p)}))}</b><p>${normal?'':esc(t('boostTravel',{seconds:I.number(Math.ceil(p.seconds*100)/100)}))}</p><small>${t('boostDepart')}: ${range(p)}</small><small>${t('boostLatest')}: <strong data-boost-deadline></strong></small>${normal?'':`<p class="boost-action">${esc(t('boostSequence',{delay:view.options.delay,items:boostItems(p)}))}</p>`}</div>${alternatives.length?`<div class="boost-alternatives"><span>${t('boostAlternatives')}</span>${alternatives.map(p=>`<p><b>${esc(boostItems(p))}</b> · ${esc(t('boostTravel',{seconds:I.number(Math.ceil(p.seconds*100)/100)}))}<small>${t('boostDepart')}: ${range(p)}</small></p>`).join('')}</div>`:''}`:`<p class="field-note">${t('boostUnavailable')}</p>`}${w.narrow?`<p class="boost-caution">${t('hospitalWarning')}</p>`:''}</article>`;
      }).join(''):`<p class="result-placeholder">${t(!enabled?'boostPaused':invalid?'boostInvalid':!march?'marchNeedsCheck':windows.some(w=>w.usable)?'boostFinished':windows.length?'noSafeWindow':'twoNeeded')}</p>`;
      view.signature=signature;
    }
    analyses.forEach((a,i)=>{const node=result.querySelector(`[data-boost-window="${i}"] [data-boost-deadline]`);if(node)node.textContent=countdown((a.recommended.end-time)/1000);});
    return analyses;
  }
  window.KingshotBattleUI={esc,countdown,localTime,orders,tick,gaps,boostAdvisor,boostItems};
})();

(function(){
  'use strict';
  const K=window.KingshotTiming,I=window.KingshotI18n,UI=window.KingshotBattleUI,t=(k,p)=>I.t(k,p),esc=UI.esc;
  function create(container,onAction){
    let data={rows:[],leaders:[],enemies:[]},signature='',working=false;
    function values(){return Object.fromEntries([...container.querySelectorAll('[name]')].map(n=>[n.name,n.value]));}
    function source(){const form=container.querySelector('form');if(!form)return;const leader=data.leaders.find(l=>l.id===form.elements.leaderId.value);for(const key of ['name','prepare','march'])form.elements[key].disabled=!!leader||working||!data.online;container.querySelector('[data-counter-new]').hidden=!!leader;container.querySelector('[data-counter-source-info]').textContent=leader?t('roomLeaderTimes',{prepare:leader.prepare,march:leader.march??'—'}):'';form.elements.remaining.closest('label').hidden=form.elements.mode.value==='planned';form.querySelector('[data-counter-save]').disabled=!data.enemies.some(e=>e.active!==false);}
    function render(){
      const readings=[...container.querySelectorAll('[data-counter-id]')].map(n=>({id:n.dataset.counterId,mode:n.querySelector('[data-counter-reading-mode]')?.value,value:n.querySelector('[data-counter-reading]')?.value}));
      const active=document.activeElement,focused=container.contains(active)?{id:active.closest('[data-counter-id]')?.dataset.counterId,name:active.name,reading:active.hasAttribute('data-counter-reading'),mode:active.hasAttribute('data-counter-reading-mode'),start:active.selectionStart,end:active.selectionEnd}:null;
      const saved=values(),open=[...container.querySelectorAll('details[open]')].map(n=>n.closest('[data-counter-id]')?.dataset.counterId);
      container.innerHTML=`<div class="panel-header"><h2>${t('counterTitle')}</h2></div><p class="panel-caption">${t('counterHelp')}</p>${data.editable?`<form class="counter-form"><fieldset><div class="field-grid"><label>${t('counterEnemy')}<select name="enemyId">${data.enemies.filter(e=>e.active!==false).map(e=>`<option value="${esc(e.id)}">${esc(e.name)} · ${K.formatUtc(e.arrivalAt)}</option>`).join('')}</select></label><label>${t('counterLeader')}<select name="leaderId">${data.leaders.map(l=>`<option value="${esc(l.id)}">${esc(l.name)}${l.enabled===false?' · '+t('leaderDisabled'):''}</option>`).join('')}<option value="">${t('counterNewLeader')}</option></select></label></div><p class="field-note" data-counter-source-info></p><div class="field-grid" data-counter-new><label>${t('name')}<input name="name" maxlength="40"></label><label>${t('prepare')}<input name="prepare" value="5:00" placeholder="5:00"></label><label>${t('march')}<input name="march" placeholder="35"></label></div><div class="field-grid"><label>${t('counterOffset')}<input name="offset" value="1" type="number" min="0.1" max="3600" step="0.1" required></label><label>${t('counterInitialMode')}<select name="mode"><option value="planned">${t('counterPlanMode')}</option><option value="gathering">${t('counterGatherMode')}</option><option value="marching">${t('counterMarchMode')}</option></select></label><label hidden>${t('counterReading')}<input name="remaining" value="4:00" placeholder="4:00"></label></div><p class="field-note">${t('counterPrecision')}</p><button type="submit" class="button secondary" data-counter-save>${t('counterSave')}</button></fieldset></form>`:''}<p class="form-error" data-counter-error role="alert" hidden></p><div class="counter-orders">${data.rows.length?data.rows.map(r=>`<article class="rally-order counter-order ${r.cancelled?'enemy-stopped':''}" data-counter-id="${esc(r.id)}"><header><b>${esc(r.name)}</b><span class="pill neutral" data-counter-stage></span></header><p class="field-note">${esc(r.enemyName)} · ${t('counterAfter',{seconds:I.number(r.offset)})}</p><div class="order-times"><div><small>${t('rallyLaunchTime')}</small><strong data-counter-launch>${K.formatUtc(r.launchAt)}</strong></div><div><small>${t('counterTarget')}</small><strong data-counter-target></strong></div><div><small>${t('attackArrival')}</small><strong>${K.formatUtc(r.arrivalAt)}</strong></div><div><small>${t('counterDrift')}</small><strong data-counter-drift></strong></div></div><div class="order-countdown"><span data-counter-clock-label></span><strong data-counter-clock></strong></div><p class="counter-warning" data-counter-warning></p>${data.editable?`<details class="launch-calibration"><summary>${t('counterCalibration')}</summary><fieldset><div class="time-nudges">${[-1,-0.1,0.1,1].map(d=>`<button type="button" data-counter-op="adjust" data-delta="${d}">${d>0?'+':'−'}${Math.abs(d)}s</button>`).join('')}</div><button type="button" class="button secondary" data-counter-op="observe" data-mode="launch">${t('launchObservedNow')}</button><div class="field-grid"><label>${t('stage')}<select data-counter-reading-mode><option value="gathering">${t('counterGatherMode')}</option><option value="marching">${t('counterMarchMode')}</option></select></label><label>${t('counterReading')}<input data-counter-reading value="0:30" placeholder="0:30"></label></div><button type="button" class="text-button" data-counter-op="observe" data-mode="reading">${t('counterRecordReading')}</button><p class="field-note">${t('counterRebaseHelp')}</p><div class="room-leader-actions"><button type="button" class="text-button" data-counter-op="rebase">${t(r.cancelled?'counterRestart':'counterRebase')}</button>${r.cancelled?'':`<button type="button" class="text-button subtle" data-counter-op="cancel">${t('counterCancel')}</button>`}</div></fieldset></details>`:''}</article>`).join(''):`<p class="result-placeholder">${t('counterEmpty')}</p>`}</div>`;
      for(const [name,value] of Object.entries(saved)){const n=container.querySelector(`[name="${name}"]`);if(n&&(!n.options||[...n.options].some(o=>o.value===value)))n.value=value;}
      for(const id of open)container.querySelector(`[data-counter-id="${CSS.escape(id)}"] details`)?.setAttribute('open','');
      for(const reading of readings){const row=container.querySelector(`[data-counter-id="${CSS.escape(reading.id)}"]`);if(row?.querySelector('[data-counter-reading]')){row.querySelector('[data-counter-reading]').value=reading.value;row.querySelector('[data-counter-reading-mode]').value=reading.mode;}}
      source();disable();
      if(focused){const row=focused.id?container.querySelector(`[data-counter-id="${CSS.escape(focused.id)}"]`):container;const n=row?.querySelector(focused.reading?'[data-counter-reading]':focused.mode?'[data-counter-reading-mode]':focused.name?`[name="${focused.name}"]`:'[data-counter-op="rebase"]');if(n){n.focus({preventScroll:true});if(focused.start!=null&&n.setSelectionRange)n.setSelectionRange(focused.start,focused.end);}}
    }
    function disable(){container.querySelectorAll('fieldset').forEach(n=>n.disabled=working||!data.online||!data.editable);source();}
    async function act(d){if(working||!data.editable||!data.online)return;working=true;disable();const error=container.querySelector('[data-counter-error]');error.hidden=true;try{const result=await onAction(d);if(d.op==='save'&&!d.leaderId){const created=result?.leaderId?result:result?.counterRows?.find(r=>r.name===d.name&&r.prepareSeconds===d.prepare&&r.marchSeconds===d.march);const select=container.querySelector('[name="leaderId"]');if(created&&select){select.value=created.leaderId;source();}}}catch(e){error.hidden=false;error.textContent=t(e.code||'roomInvalid');}finally{working=false;disable();}}
    container.addEventListener('change',e=>{if(['leaderId','mode'].includes(e.target.name))source();});
    container.addEventListener('submit',e=>{if(!e.target.matches('.counter-form'))return;e.preventDefault();const d=values();try{const old=data.rows.find(r=>r.leaderId===d.leaderId);act({...d,op:'save',id:old?.id||'',revision:old?.revision||0,offset:K.parseDuration(d.offset,false),prepare:d.leaderId?null:K.parseDuration(d.prepare),march:d.leaderId?null:K.parseDuration(d.march,false),remaining:d.mode==='planned'?null:K.parseDuration(d.remaining),enemyRevision:data.enemies.find(r=>r.id===d.enemyId)?.revision??0,enemyRecordedAt:data.enemies.find(r=>r.id===d.enemyId)?.recordedAt});}catch(e){const n=container.querySelector('[data-counter-error]');n.hidden=false;n.textContent=t(e.code||'invalidTime');}});
    container.addEventListener('click',e=>{const b=e.target.closest('[data-counter-op]');if(!b)return;const card=b.closest('[data-counter-id]'),row=data.rows.find(r=>r.id===card.dataset.counterId);if(!row)return;try{const mode=b.dataset.mode==='reading'?card.querySelector('[data-counter-reading-mode]').value:b.dataset.mode;act({op:b.dataset.counterOp,id:row.id,revision:row.revision,...(b.dataset.delta?{delta:Number(b.dataset.delta)}:{}),...(mode?{mode,remaining:mode==='launch'?null:K.parseDuration(card.querySelector('[data-counter-reading]').value)}:{})});}catch(e){const n=container.querySelector('[data-counter-error]');n.hidden=false;n.textContent=t(e.code||'invalidTime');}});
    function tick(time){
      for(const r of data.rows){const card=container.querySelector(`[data-counter-id="${CSS.escape(r.id)}"]`),s=K.counterStatus(r,data.enemies,time,data.leaders);if(!card)continue;
        const text=(key,value)=>{const node=card.querySelector(`[data-counter-${key}]`);if(node.textContent!==value)node.textContent=value;};
        const blocked=s.sourceChanged||s.leaderChanged,key=r.cancelled?'counterStopped':!r.confirmed&&blocked?'counterNeedsReview':s.missed?'counterMissed':s.stage==='waiting'?'launchCountdown':s.stage==='launch'?'launchNow':s.stage==='gathering'?'prepareRemaining':s.stage==='marching'?'marchRemaining':'arrived';
        text('stage',t(key));text('clock-label',t(key));text('clock',r.cancelled||!r.confirmed&&blocked||s.missed?'—':s.stage==='launch'?t('launchNow'):UI.countdown(s.remaining));text('target',K.formatUtc(s.desiredAt));text('drift',(s.drift>0?'+':'')+I.number(Math.round(s.drift*10)/10)+' '+t('seconds'));
        text('warning',[s.sourceChanged?t('counterSourceChanged'):'',s.leaderChanged?t('counterLeaderChanged'):'',s.missed?t('counterMissedHelp'):'',s.nextThreat?t('counterNextThreat',{name:s.nextThreat.name}):''].filter(Boolean).join(' '));
        card.classList.toggle('counter-review',!r.cancelled&&(blocked||s.missed||s.drift<0));
        card.querySelectorAll('[data-counter-op="observe"],[data-counter-op="adjust"]').forEach(b=>b.disabled=r.cancelled);
      }
    }
    return {update(next,time){data={...next,rows:next.rows||[],online:next.online!==false};const key=JSON.stringify([I.language,data.editable,data.leaders,data.enemies,data.rows]);if(key!==signature){signature=key;render();}else disable();tick(time);},tick};
  }
  window.KingshotCounterUI={create};
})();
